const recordBuddyMockReminder = `-- name: RecordBuddyMockReminder :execrows
INSERT INTO buddy_mock_reminders (mock_id, offset_minutes)
SELECT m.id, $1::int
FROM buddy_mocks m
WHERE m.id = $2 AND m.status = 'confirmed' AND m.starts_at > now()
ON CONFLICT DO NOTHING
`

type RecordBuddyMockReminderParams struct {
	OffsetMinutes int32       `json:"offset_minutes"`
	MockID        pgtype.UUID `json:"mock_id"`
}

// Claim one reminder. Zero rows means another run holds it, or the mock was cancelled or
// has started since the due read: send only after this returns 1. The status is checked
// here, in the claim, because a batch leaves time between that read and this statement.
func (q *Queries) RecordBuddyMockReminder(ctx context.Context, arg RecordBuddyMockReminderParams) (int64, error) {
	result, err := q.db.Exec(ctx, recordBuddyMockReminder, arg.OffsetMinutes, arg.MockID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const replaceBuddyMockWeekly = `-- name: ReplaceBuddyMockWeekly :exec
WITH cleared AS (
    DELETE FROM buddy_mock_availability
    WHERE user_id = $1::bigint AND weekday IS NOT NULL
)
INSERT INTO buddy_mock_availability (user_id, weekday, start_time, end_time)
SELECT $1::bigint, w.weekday, s.start_time, e.end_time
FROM unnest($2::smallint[]) WITH ORDINALITY AS w (weekday, ord)
JOIN unnest($3::time[]) WITH ORDINALITY AS s (start_time, ord) ON s.ord = w.ord
JOIN unnest($4::time[]) WITH ORDINALITY AS e (end_time, ord) ON e.ord = w.ord
`

type ReplaceBuddyMockWeeklyParams struct {
	UserID     int64         `json:"user_id"`
	Weekdays   []int16       `json:"weekdays"`
	StartTimes []pgtype.Time `json:"start_times"`
	EndTimes   []pgtype.Time `json:"end_times"`
}

// Swap the recurring week in one statement, leaving dated overrides alone: half of the
// edit applied is a member bookable at hours they just removed. The three arrays are one
// row each, zipped back by position (WITH ORDINALITY: sqlc's analyzer does not resolve the
// multi-array form of unnest).
func (q *Queries) ReplaceBuddyMockWeekly(ctx context.Context, arg ReplaceBuddyMockWeeklyParams) error {
	_, err := q.db.Exec(ctx, replaceBuddyMockWeekly,
		arg.UserID,
		arg.Weekdays,
		arg.StartTimes,
		arg.EndTimes,
	)
	return err
}

const upsertBuddyMockSettings = `-- name: UpsertBuddyMockSettings :one
INSERT INTO buddy_mock_settings (user_id, timezone, meeting_url, topics, paused)
VALUES ($1, $2, $3, $4::text[], $5)
ON CONFLICT (user_id) DO UPDATE
SET timezone = EXCLUDED.timezone, meeting_url = EXCLUDED.meeting_url, topics = EXCLUDED.topics,
    paused = EXCLUDED.paused, updated_at = now()
RETURNING user_id, timezone, meeting_url, topics, paused, created_at, updated_at
`

type UpsertBuddyMockSettingsParams struct {
	UserID     int64    `json:"user_id"`
	Timezone   string   `json:"timezone"`
	MeetingUrl string   `json:"meeting_url"`
	Topics     []string `json:"topics"`
	Paused     bool     `json:"paused"`
}

// Save the whole settings block. The service validates zone, link and topics first; the
// CHECKs repeat the link and topic rules so no other writer can skip them.
func (q *Queries) UpsertBuddyMockSettings(ctx context.Context, arg UpsertBuddyMockSettingsParams) (BuddyMockSetting, error) {
	row := q.db.QueryRow(ctx, upsertBuddyMockSettings,
		arg.UserID,
		arg.Timezone,
		arg.MeetingUrl,
		arg.Topics,
		arg.Paused,
	)
	var i BuddyMockSetting
	err := row.Scan(
		&i.UserID,
		&i.Timezone,
		&i.MeetingUrl,
		&i.Topics,
		&i.Paused,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
